package com.vr3th.mediacompressor.ui.screens
import androidx.compose.foundation.layout.*;import androidx.compose.foundation.lazy.LazyColumn;import androidx.compose.foundation.lazy.items;import androidx.compose.material3.*;import androidx.compose.runtime.Composable;import androidx.compose.ui.Modifier;import androidx.compose.ui.unit.dp;import com.vr3th.mediacompressor.data.HistoryItem;import com.vr3th.mediacompressor.utils.FormatUtils
@Composable fun HistoryScreen(historyList:List<HistoryItem>,onClear:()->Unit,onBack:()->Unit){Column(Modifier.fillMaxSize().padding(20.dp)){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text("History",style=MaterialTheme.typography.titleLarge);TextButton(onClick=onClear){Text("Clear")}};if(historyList.isEmpty())Text("No history recorded yet.")else LazyColumn(verticalArrangement=Arrangement.spacedBy(10.dp)){items(historyList){i->Card(Modifier.fillMaxWidth()){Column(Modifier.padding(14.dp)){Text(i.fileName);Text("${FormatUtils.formatFileSize(i.originalSize)} → ${FormatUtils.formatFileSize(i.compressedSize)} (${FormatUtils.calculateReduction(i.originalSize,i.compressedSize)})")}}}};TextButton(onClick=onBack){Text("Back")}}}
